description:
Objective:
Deterministic SQLite -> canonical snapshot. `serializeCampaign(db)` returns ordered
`SnapshotRecord[]` (schema records then row records); `canonicalize(records)`
renders a byte-stable string. Same SQLite content => identical bytes.

Files:
- Create: `packages/core/src/persistence/checkpoint/serialize.ts`
- Modify: `packages/core/src/index.ts`
- Test:   `packages/core/test/checkpoint.serialize.test.ts`

Steps:

1. Write the failing test `packages/core/test/checkpoint.serialize.test.ts`:
```ts
import { describe, expect, it } from 'vitest';
import { openDatabase } from '../src/persistence/db.js';
import {
  serializeCampaign,
  canonicalize,
} from '../src/persistence/checkpoint/serialize.js';

function seed(rowsReversed: boolean) {
  const db = openDatabase(':memory:');
  db.exec('CREATE TABLE meta (key TEXT PRIMARY KEY, value TEXT NOT NULL);');
  db.exec('CREATE TABLE notes (id INTEGER PRIMARY KEY, body TEXT);');
  const pairs = [
    ['b', '2'],
    ['a', '1'],
  ];
  for (const [k, v] of rowsReversed ? [...pairs].reverse() : pairs) {
    db.prepare('INSERT INTO meta(key, value) VALUES (?, ?)').run(k, v);
  }
  db.prepare('INSERT INTO notes(id, body) VALUES (?, ?)').run(1, null);
  return db;
}

describe('deterministic serialization', () => {
  it('is identical regardless of physical insert order', () => {
    const s1 = canonicalize(serializeCampaign(seed(false)));
    const s2 = canonicalize(serializeCampaign(seed(true)));
    expect(s1).toBe(s2);
  });

  it('orders tables by name and is stable across runs', () => {
    const s1 = canonicalize(serializeCampaign(seed(false)));
    const s2 = canonicalize(serializeCampaign(seed(false)));
    expect(s1).toBe(s2);
    expect(s1.indexOf('"table":"meta"')).toBeLessThan(
      s1.indexOf('"table":"notes"'),
    );
  });

  it('excludes sqlite internal tables', () => {
    const s = canonicalize(serializeCampaign(seed(false)));
    expect(s).not.toContain('sqlite_');
  });
});
```

2. Run it to verify FAIL.
   Command: `npx vitest run packages/core/test/checkpoint.serialize.test.ts`
   Expected: FAIL — module not found.

3. Create `packages/core/src/persistence/checkpoint/serialize.ts`:
```ts
import type { Db } from '../db.js';

export interface SnapshotRecord {
  table: string;
  kind: 'schema' | 'row';
  ordinal: number;
  payload: string;
}

interface MasterRow {
  name: string;
  sql: string | null;
}

export function serializeCampaign(db: Db): SnapshotRecord[] {
  const tables = (
    db
      .prepare(
        "SELECT name, sql FROM sqlite_master WHERE type='table' " +
          "AND name NOT LIKE 'sqlite_%' ORDER BY name",
      )
      .all() as MasterRow[]
  ).filter((t) => t.sql !== null);

  const records: SnapshotRecord[] = [];

  for (const t of tables) {
    records.push({
      table: t.name,
      kind: 'schema',
      ordinal: 0,
      payload: JSON.stringify({ create: t.sql }),
    });
  }
  for (const t of tables) {
    const rows = db.prepare(`SELECT * FROM "${t.name}"`).all() as Record<
      string,
      unknown
    >[];
    const encoded = rows
      .map((r) => canonicalRow(r))
      .sort((x, y) => (x < y ? -1 : x > y ? 1 : 0));
    encoded.forEach((payload, i) => {
      records.push({ table: t.name, kind: 'row', ordinal: i, payload });
    });
  }
  return records;
}

function canonicalRow(row: Record<string, unknown>): string {
  const keys = Object.keys(row).sort();
  const obj: Record<string, unknown> = {};
  for (const k of keys) {
    const v = row[k];
    obj[k] = Buffer.isBuffer(v) ? { __blob: v.toString('base64') } : v;
  }
  return JSON.stringify(obj);
}

export function canonicalize(records: SnapshotRecord[]): string {
  return records
    .map(
      (r) =>
        `{"table":${JSON.stringify(r.table)},"kind":${JSON.stringify(
          r.kind,
        )},"ordinal":${r.ordinal},"payload":${JSON.stringify(r.payload)}}`,
    )
    .join('\n');
}
```

4. Add to `packages/core/src/index.ts` (append):
```ts
