export type { SnapshotRecord } from './persistence/checkpoint/serialize.js';
```

5. Run the test to verify PASS.
   Command: `npx vitest run packages/core/test/checkpoint.serialize.test.ts`
   Expected: 3 passed.

6. Typecheck.
   Command: `npm run build`
   Expected: exit 0.

